var HINTS = [["Move", "WASD"], ["Dodge", "Space"], ["Sprint", "hold Space"], ["Attack", "J / LMB"], ["Heavy", "K / RMB"], ["Skill", "L"], ["Parry", "Shift"], ["Ink", "hold I"], ["Options", "O"]];
var HINT_SECONDS = 10;
var FLASH_FULL = 0.25;
